          <span class="row-value">العربية</span>
        </div>
        <span class="chevron">›</span>
      </div>
    </div>

    <!-- الأمان -->
    <div class="card">
      <div class="group-title">الأمان</div>

      <div class="row">
        <div class="row-label">
          <span class="title">التعرف البيومتري (Face ID)</span>
